import type { PatenteHistorico } from './Seccion7_6Patentes';

interface FilaCambioGiro {
  numero: string;
  fecha: string;
  fechaPublicacion: string;
  tieneEfectosGenerales: 'Sí' | 'No';
  descripcion: string;
  ultimaActualizacion?: string;
  enlaceModificacion?: string;
  tipoNorma?: string;
  nombreTitulo?: string;
}

const crearRegistrosCambioGiro = (filas: FilaCambioGiro[]): PatenteHistorico[] =>
  filas.map(({
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    descripcion,
    ultimaActualizacion = 'Sin Modificaciones',
    enlaceModificacion = 'Sin Modificaciones',
    tipoNorma,
    nombreTitulo = 'Cambio de Giro'
  }) => ({
    tipoNorma: tipoNorma ?? 'Decretos Exentos',
    denominacion: 'Patentes y Permisos',
    nombreTitulo,
    numero,
    fecha,
    fechaPublicacion,
    tieneEfectosGenerales,
    ultimaActualizacion,
    descripcion,
    enlacePublicacion: 'PDF',
    enlaceModificacion,
    urlPublicacion: '',
    urlModificacion: ''
  }));

